ALTER TABLE public.approval_requests ADD COLUMN expires_at timestamptz NOT NULL DEFAULT(now()+interval '24 hours');
CREATE OR REPLACE FUNCTION public.staff_financial_payload(_table text,_j jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb; BEGIN
 IF _table='payouts' THEN p:=jsonb_build_object('operation','payout','vendor_id',_j->>'vendor_id','amount',(_j->>'amount')::numeric,'from_account_id',_j->>'from_account_id','vendor_account_id',_j->>'vendor_account_id','period_start',_j->>'period_start','period_end',_j->>'period_end','reference_no',nullif(trim(_j->>'reference_no'),''),'destination_version',(SELECT md5(coalesce(account_number,'')||coalesce(account_title,'')||coalesce(bank_name,'')) FROM vendor_bank_accounts WHERE id=(_j->>'vendor_account_id')::uuid AND user_id=(_j->>'vendor_id')::uuid AND is_active));
 ELSIF _table='rider_salary_payouts' THEN p:=jsonb_build_object('operation','rider_pay','rider_id',_j->>'rider_id','total',(_j->>'total')::numeric,'salary_amount',(_j->>'salary_amount')::numeric,'bonus',(_j->>'bonus')::numeric,'deduction',(_j->>'deduction')::numeric,'order_earnings',(_j->>'order_earnings')::numeric,'period_start',_j->>'period_start','period_end',_j->>'period_end','from_account_id',_j->>'from_account_id','reference_no',nullif(trim(_j->>'reference_no'),''));
 ELSIF _table='refunds' THEN p:=jsonb_build_object('operation','refund','order_id',_j->>'order_id','order_kind',_j->>'order_kind','customer_id',_j->>'customer_id','amount',(_j->>'amount')::numeric,'refund_type',_j->>'refund_type'); ELSE RAISE EXCEPTION 'Unsupported financial operation'; END IF; RETURN p; END $$;
CREATE OR REPLACE FUNCTION public.staff_approval_allowed(_kind text,_ref text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT has_permission(auth.uid(),'approve') THEN RETURN false; END IF; IF _kind='payout' THEN RETURN staff_vendor_allowed(_ref::uuid); ELSIF _kind='refund' THEN RETURN staff_order_allowed('finance','food',_ref::uuid) OR staff_order_allowed('finance','grocery_cart',_ref::uuid) OR staff_order_allowed('finance','grocery_list',_ref::uuid) OR staff_order_allowed('finance','service',_ref::uuid); ELSE RETURN staff_rider_allowed('finance',_ref::uuid); END IF; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;
CREATE OR REPLACE FUNCTION public.request_secure_approval(_kind text,_reference_id uuid,_amount numeric,_payload jsonb,_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb; result uuid; t text; BEGIN
 IF _amount IS NULL OR _amount<=0 OR length(trim(coalesce(_note,'')))<3 THEN RAISE EXCEPTION 'Exact positive amount and reason required'; END IF;
 IF _kind='payout' THEN IF NOT staff_vendor_allowed(_reference_id) THEN RAISE EXCEPTION 'Vendor scope denied'; END IF; t:='payouts'; IF (_payload->>'vendor_id') IS DISTINCT FROM _reference_id::text OR (_payload->>'amount')::numeric IS DISTINCT FROM _amount THEN RAISE EXCEPTION 'Recipient or amount mismatch'; END IF;
 ELSIF _kind='refund' THEN IF NOT (staff_order_allowed('support',_payload->>'order_kind',_reference_id) OR staff_order_allowed('finance',_payload->>'order_kind',_reference_id)) THEN RAISE EXCEPTION 'Order scope denied'; END IF; t:='refunds'; IF (_payload->>'order_id') IS DISTINCT FROM _reference_id::text OR (_payload->>'amount')::numeric IS DISTINCT FROM _amount THEN RAISE EXCEPTION 'Refund mismatch'; END IF;
 ELSIF _kind='other' AND _payload->>'operation'='rider_pay' THEN IF NOT staff_rider_allowed('finance',_reference_id) THEN RAISE EXCEPTION 'Rider scope denied'; END IF; t:='rider_salary_payouts'; IF (_payload->>'rider_id') IS DISTINCT FROM _reference_id::text OR (_payload->>'total')::numeric IS DISTINCT FROM _amount THEN RAISE EXCEPTION 'Rider payment mismatch'; END IF;
 ELSE RAISE EXCEPTION 'Unsupported exact operation'; END IF;
 p:=staff_financial_payload(t,_payload);
 IF t IN ('payouts','rider_salary_payouts') AND ((p->>'from_account_id') IS NULL OR (p->>'period_start') IS NULL OR (p->>'period_end') IS NULL OR (p->>'period_end')::date<(p->>'period_start')::date) THEN RAISE EXCEPTION 'Source account and valid period required'; END IF;
 IF t='payouts' AND p->>'destination_version' IS NULL THEN RAISE EXCEPTION 'Active destination required'; END IF;
 IF t='rider_salary_payouts' AND ((p->>'salary_amount')::numeric<0 OR (p->>'bonus')::numeric<0 OR (p->>'deduction')::numeric<0 OR (p->>'order_earnings') IS NULL) THEN RAISE EXCEPTION 'Nonnegative payment components required'; END IF;
 INSERT INTO approval_requests(kind,reference_id,amount,payload,note,requested_by) VALUES(_kind,_reference_id::text,_amount,p,left(_note,500),auth.uid()) RETURNING id INTO result;
 INSERT INTO staff_audit_log(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),'request','approval_requests',result::text,jsonb_build_object('kind',_kind,'amount',_amount,'exact',true)); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.request_approval(_kind text,_amount numeric,_reference_id text,_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'عین ادائیگی کی تفصیل سے نئی درخواست بنائیں؛ صرف رقم کی منظوری کافی نہیں'; END $$;
CREATE OR REPLACE FUNCTION public.decide_approval(_id uuid,_approve boolean,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r approval_requests; BEGIN SELECT * INTO r FROM approval_requests WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.status<>'pending' OR r.expires_at<=now() OR r.payload='{}'::jsonb THEN RAISE EXCEPTION 'Request expired, incomplete or not pending'; END IF; IF NOT staff_approval_allowed(r.kind,r.reference_id) THEN RAISE EXCEPTION 'Approval outside assigned scope'; END IF; IF r.requested_by=auth.uid() THEN RAISE EXCEPTION 'requester cannot approve own request'; END IF; IF NOT staff_enabled(r.requested_by) THEN RAISE EXCEPTION 'Requester suspended'; END IF; IF NOT _approve AND length(trim(coalesce(_note,'')))<3 THEN RAISE EXCEPTION 'Rejection reason required'; END IF; UPDATE approval_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,decided_by=auth.uid(),decision_note=left(_note,500),decided_at=now() WHERE id=_id; INSERT INTO staff_audit_log(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),CASE WHEN _approve THEN 'approve' ELSE 'reject' END,'approval_requests',_id::text,jsonb_build_object('kind',r.kind,'amount',r.amount)); END $$;
CREATE OR REPLACE FUNCTION public.enforce_two_person_approval() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j jsonb:=to_jsonb(NEW); p jsonb; k text; ref text; amt numeric; req uuid; reason text; BEGIN
 IF auth.uid() IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN IF TG_TABLE_NAME='refunds' THEN IF (j-ARRAY['status','approved_by','completed_at','updated_at','provider_reference']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','approved_by','completed_at','updated_at','provider_reference']) THEN RAISE EXCEPTION 'Approved financial terms are immutable'; END IF; IF NEW.status IS NOT DISTINCT FROM OLD.status OR NEW.status NOT IN ('approved','completed') OR OLD.status IN ('approved','completed') THEN RETURN NEW; END IF; ELSE RAISE EXCEPTION 'Financial approval trigger misuse'; END IF; END IF;
 IF TG_TABLE_NAME='payouts' THEN k:='payout'; ref:=NEW.vendor_id::text; amt:=NEW.amount; reason:=NEW.notes;
 ELSIF TG_TABLE_NAME='rider_salary_payouts' THEN k:='other';ref:=NEW.rider_id::text;amt:=NEW.total;reason:=NEW.note;
 ELSE k:='refund';ref:=NEW.order_id::text;amt:=NEW.amount;reason:=NEW.reason; IF amt<=2000 THEN RETURN NEW; END IF; END IF;
 p:=staff_financial_payload(TG_TABLE_NAME,j);
 IF EXISTS(SELECT 1 FROM app_owner WHERE user_id=auth.uid()) THEN IF length(trim(coalesce(reason,'')))<3 THEN RAISE EXCEPTION 'Owner exception reason required'; END IF; INSERT INTO staff_audit_log(actor_id,action,entity_type,entity_id,details) VALUES(auth.uid(),'owner_financial_exception',TG_TABLE_NAME,NEW.id::text,jsonb_build_object('kind',k,'amount',amt,'reason_recorded',true)); RETURN NEW; END IF;
 IF NOT has_permission(auth.uid(),'finance') THEN RAISE EXCEPTION 'Financial execution permission required'; END IF;
 SELECT id INTO req FROM approval_requests WHERE kind=k AND reference_id=ref AND amount=amt AND payload=p AND status='approved' AND used_at IS NULL AND expires_at>now() AND requested_by=auth.uid() AND decided_by<>auth.uid() AND staff_enabled(decided_by) ORDER BY decided_at,id LIMIT 1 FOR UPDATE;
 IF req IS NULL THEN RAISE EXCEPTION 'عین رقم، وصول کنندہ، اکاؤنٹ اور مدت کی آزاد منظوری درکار ہے'; END IF;
 UPDATE approval_requests SET used_at=now() WHERE id=req; RETURN NEW; END $$;
CREATE TRIGGER rider_pay_exact_approval BEFORE INSERT ON public.rider_salary_payouts FOR EACH ROW EXECUTE FUNCTION public.enforce_two_person_approval();
CREATE TRIGGER refund_update_exact_approval BEFORE UPDATE ON public.refunds FOR EACH ROW EXECUTE FUNCTION public.enforce_two_person_approval();
CREATE OR REPLACE FUNCTION public.guard_approval_terms() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF (NEW.kind,NEW.reference_id,NEW.amount,NEW.payload,NEW.requested_by,NEW.expires_at) IS DISTINCT FROM (OLD.kind,OLD.reference_id,OLD.amount,OLD.payload,OLD.requested_by,OLD.expires_at) THEN RAISE EXCEPTION 'Approval terms are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER approval_terms_immutable BEFORE UPDATE ON public.approval_requests FOR EACH ROW EXECUTE FUNCTION public.guard_approval_terms();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.pay_rider(uuid,date,date,numeric,numeric,numeric,uuid,text,text)'::regprocedure) INTO d; IF position('SELECT COALESCE(SUM(amount),0)' in d)=0 THEN RAISE EXCEPTION 'Rider pay anchor missing'; END IF; d:=replace(d,'SELECT COALESCE(SUM(amount),0)',E'IF _salary IS NULL OR _bonus IS NULL OR _deduction IS NULL OR _salary<0 OR _bonus<0 OR _deduction<0 OR _from_account_id IS NULL OR length(trim(coalesce(_note,\'\')))<3 THEN RAISE EXCEPTION \'Account, reason and nonnegative values required\'; END IF;\n PERFORM pg_advisory_xact_lock(hashtextextended(\'rider-pay:\'||_rider::text,0));\n IF EXISTS(SELECT 1 FROM rider_salary_payouts WHERE rider_id=_rider AND status<>\'cancelled\' AND period_start<=_period_end AND period_end>=_period_start AND (_salary>0 OR _bonus>0 OR _deduction>0)) THEN RAISE EXCEPTION \'Overlapping salary or adjustment period already paid\'; END IF;\n SELECT COALESCE(SUM(amount),0)'); EXECUTE d;
 SELECT pg_get_functiondef('public.admin_pay_vendor(uuid,numeric,uuid,uuid,date,date,text,text)'::regprocedure) INTO d; IF position('_payable := public.vendor_payable' in d)=0 THEN RAISE EXCEPTION 'Vendor pay anchor missing'; END IF;d:=replace(d,'_payable := public.vendor_payable',E'PERFORM pg_advisory_xact_lock(hashtextextended(\'vendor-pay:\'||_vendor_id::text,0));\n IF NOT EXISTS(SELECT 1 FROM vendor_bank_accounts WHERE id=_vendor_account_id AND user_id=_vendor_id AND is_active) THEN RAISE EXCEPTION \'Active recipient account required\'; END IF;\n _payable := public.vendor_payable'); EXECUTE d; END $$;
REVOKE ALL ON FUNCTION public.staff_financial_payload(text,jsonb),public.request_secure_approval(text,uuid,numeric,jsonb,text),public.guard_approval_terms() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_financial_payload(text,jsonb),public.request_secure_approval(text,uuid,numeric,jsonb,text) TO authenticated,service_role;